    if self.expectedRevision != 0 {
      try visitor.visitSingularInt64Field(value: self.expectedRevision, fieldNumber: 1)
    }
    if self.actualRevision != 0 {
      try visitor.visitSingularInt64Field(value: self.actualRevision, fieldNumber: 2)
    }
    if !self.scope.isEmpty {
      try visitor.visitSingularStringField(value: self.scope, fieldNumber: 3)
    }
    try unknownFields.traverse(visitor: &visitor)
  }

  public static func ==(lhs: Yiru_Runtime_V1_LayoutRevisionConflict, rhs: Yiru_Runtime_V1_LayoutRevisionConflict) -> Bool {
    if lhs.expectedRevision != rhs.expectedRevision {return false}
    if lhs.actualRevision != rhs.actualRevision {return false}
    if lhs.scope != rhs.scope {return false}
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
